import React, { useState, useRef, useEffect } from "react";
import { useLocation, useNavigate } from 'react-router-dom';
import { Stage, Layer, Circle, Image as KonvaImage, Text, Group } from "react-konva";
import useImage from "use-image";
import "./wall.css";
import { RouteActions } from "./routeActions";
import RouterToast from "../components/toast";

const Wall = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const params = new URLSearchParams(location.search);
    const imageUrl = location.state?.preselectWall || params.get("image");
    const [image] = useImage(imageUrl);

    const containerRef = useRef(null);
    const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

    const [isHovering, setIsHovering] = useState(false);

    const { getRoutesByWall, onSubmitRoute, onUpdateRoute } = RouteActions();
    const [wallName, setWallName] = useState("");
    const [wallRoutes, setWallRoutes] = useState([]);
    const [circles, setCircles] = useState([]);
    const [toastMessage, setToastMessage] = useState("");
    const [toastType, setToastType] = useState("success");
    const [showToast, setShowToast] = useState(false);

    const isFromDrafts = location.state?.isFromDrafts;
    const routeData = location.state?.routeData;
    const isPlacingRoute = location.state?.isPlacingRoute || false;
    const routeName = location.state?.routeName;
    const grade = location.state?.grade;
    const incline = location.state?.incline;
    const description = location.state?.description;
    const notes = location.state?.notes;
    const timestamp = location.state?.timestamp;
    const imagePath = location.state?.image;
    const comments = location.state?.comments;
    const coordinates = circles[0];
    const color = location.state?.color;
    const placingColor = isFromDrafts ? routeData?.color : color;
    const id = location.state?.id;

    const annotations = location.state?.annotations; // AC 
    const isAnnotate = location.state?.isAnnotate;


    // Extracts only the name of the wall. For example: "east-wall" or "fs1"
    useEffect(() => {
        if (imageUrl) {
            const parts = imageUrl.split('/');
            const fileName = parts[parts.length - 1];
            const nameWithoutExtension = fileName.split('.')[0];
            setWallName(nameWithoutExtension);
        }
    }, [imageUrl]);

    // shows toast on error or success
    useEffect(() => {
        if (showToast) {
            const timer = setTimeout(() => setShowToast(false), 3000);
            return () => clearTimeout(timer);
        }
    }, [showToast]);

    // Fetches all routes that belong to this wall
    useEffect(() => {
        const fetchRoutes = async () => {
            if (wallName) {
                const routes = await getRoutesByWall(wallName);
                setWallRoutes(routes);
            }
        };

        fetchRoutes();
    }, [wallName]);

    // Padding initializations for top and bottom
    const paddingTop = 20;
    const paddingBottom = 20;

    useEffect(() => {
        if (containerRef.current) {
            const rect = containerRef.current.getBoundingClientRect();
            setContainerSize({ width: rect.width, height: rect.height });
        }
    }, [imageUrl]);

    const scale = image
        ? Math.min(containerSize.width / image.width, (containerSize.height - paddingTop - paddingBottom) / image.height) // Adjust scale according to padding
        : 1;

    // Populating circles/routes that belong to this wall via their coordinates
    const plotRouteCircles = () => {
        return wallRoutes.map((route, idx) => {
            const { x, y } = route.coordinates || {};
            if (x && y && x !== 0 && y !== 0 && x != null && y != null) {
                const imageX = (containerSize.width - image.width * scale) / 2;
                const imageY = (containerSize.height - image.height * scale - paddingTop - paddingBottom) / 2 + paddingTop;

                const circleX = x * scale + imageX;
                const circleY = y * scale + imageY;

                const goReviewRoute = () => {
                    if (isPlacingRoute == false) {
                        navigate(`/review/${route.id}`);
                    }
                };

                return (
                    <Group
                        key={idx}
                        onClick={goReviewRoute}
                        {...(!isPlacingRoute && {
                            onMouseEnter: (e) => {
                                const container = e.target.getStage().container();
                                container.style.cursor = 'pointer';
                            },
                            onMouseLeave: (e) => {
                                const container = e.target.getStage().container();
                                container.style.cursor = 'default';
                            },
                        })}
                    >
                        <Circle
                            x={circleX}
                            y={circleY}
                            radius={11}
                            fill={route.color}
                            stroke="black"
                            strokeWidth={0.5}
                        />
                        <Text
                            x={circleX - 7}
                            y={circleY - 5}
                            text={route.grade}
                            fontSize={12}
                            fill="white"
                            fontStyle="bold"
                        />
                    </Group>
                );
            }
            return null;
        });
    };



    // handles resizing
    useEffect(() => {
        const handleResize = () => {
            if (containerRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                setContainerSize({ width: rect.width, height: rect.height });
            }
        };

        window.addEventListener("resize", handleResize);
        handleResize();

        return () => window.removeEventListener("resize", handleResize);
    }, [imageUrl]);

    // Placing a new route on the wall
    const placeCircle = async (e) => {
        // Checks if isPlacingRoute is true
        if (!isPlacingRoute || !image) return;

        // User can't place a route with right-click. ONLY left-click permitted
        if (e.evt.button !== 0) return;

        // Get pointer position relative to stage
        const stage = e.target.getStage();
        const pointerPos = stage.getPointerPosition();

        // Calculate offsets
        const imageX = (containerSize.width - image.width * scale) / 2;
        const imageY = (containerSize.height - image.height * scale - paddingTop - paddingBottom) / 2 + paddingTop;

        // Convert to image-native coordinates
        const x = (pointerPos.x - imageX) / scale;
        const y = (pointerPos.y - imageY) / scale;

        // Save to state
        const newCircle = { x, y };
        setCircles([newCircle]);

    };

    // going back to map page, in the case that the user changes their mind and doesn't want this wall.
    const prevPage = () => {
        navigate('/map', {
            state:
            {
                isFromDrafts,
                routeData,
                isPlacingRoute,
                routeName,
                grade,
                incline,
                description,
                notes,
                timestamp,
                image: imagePath,
                comments,
                coordinates,
                wall: "",
                color,
                id,
                annotations // AC
            }
        });
    }

    const onFinalPlaceRoute = async (e) => {
        e.preventDefault();
        try {
            const { x, y } = circles[0]

            // ALLISON ACTIVELY LOOKING INTO 
            await onSubmitRoute({ name: routeName, grade, incline, description, notes, timestamp, image: imagePath, comments, coordinates: { x, y }, wall: wallName, color, annotations, isAnnotate }); // AC

            setToastMessage("Route has been published!");
            setToastType("success");
            setShowToast(true);

            // once route is successfully published, refresh page
            navigate(`/map`, {
                state: {
                    isPlacingRoute: false,
                    isRoutePublished: true
                }
            });
        } catch (error) {
            console.error("Error with publishing route :(", error);
            setToastMessage("Failed to publish the route.");
            setToastType("danger");
            setShowToast(true);
        }
    };

    const onEditingRoute = async (e) => {
        e.preventDefault();
        try {
            const { x, y } = circles[0]

            /* ALLISON ACTIVELY CHANGING ******/
            await onUpdateRoute({ id, name: routeName, grade, incline, description, notes, timestamp, image: imagePath, comments, coordinates: { x, y }, wall: wallName, color, annotations, isAnnotate })

            setToastMessage("Route has been updated!");
            setToastType("success");
            setShowToast(true);

            // once route is successfully published, refresh page
            navigate(`/map`, {
                state: {
                    isPlacingRoute: false,
                    isRoutePublished : true
                }
            });
        } catch (error) {
            console.error("Error with updating route :(", error);
            setToastMessage("Failed to update the route.");
            setToastType("danger");
            setShowToast(true);
        }
    };

    const toCreatePage = () => {
        navigate(`/create`, {
            state:{
                preselectWall : imageUrl
            }
        });
    }

    return (
        <div>
            {showToast && (
                <div style={{ position: "fixed", top: 20, right: 20, zIndex: 9999 }}>
                    <RouterToast message={toastMessage} type={toastType} />
                </div>
            )}
            {/* for icon buttons (credit below) */}
            <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css"></link>
            <div className="header">
                <button type='button' className='back-button' onClick={prevPage}><i class="fa fa-arrow-left"></i>  Back</button>
            {!isPlacingRoute && (<h1 className={`wall-header ${isPlacingRoute ? "placing-a-route-margin" : ""}`}><b>SELECT A ROUTE TO REVIEW</b></h1>)}
            {isPlacingRoute && (<h1 className={`wall-header ${isPlacingRoute ? "placing-a-route-margin" : ""}`}><b>PLACE</b> your route on the wall, and then <b>PUBLISH</b></h1>)}
                {!isPlacingRoute && (<button type='button' className='button-and-label wall-button-and-label' onClick={toCreatePage} onMouseEnter={() => setIsHovering(true)} onMouseLeave={() => setIsHovering(false)}> + </button>)}
            </div>
            {isPlacingRoute && (
                <div className='submit-button-con'>
                    <button type='button' className="publish-route" onClick={isFromDrafts ? onEditingRoute : onFinalPlaceRoute} disabled={circles.length === 0}>
                        Publish Route
                    </button>
                </div>
            )}
            <p className={`${isHovering ? "hover-cursor" : "unhover-cursor"} wall-tip`}>CREATE A NEW ROUTE</p>
            <div className="wall-con" ref={containerRef}>
                {image && (
                    <Stage
                        width={containerSize.width}
                        height={containerSize.height}
                        onClick={placeCircle}
                    >
                        <Layer>
                            {/* Scaled image with padding */}
                            <KonvaImage
                                image={image}
                                x={(containerSize.width - image.width * scale) / 2}
                                y={(containerSize.height - image.height * scale - paddingTop - paddingBottom) / 2 + paddingTop}
                                scaleX={scale}
                                scaleY={scale}
                            />

                            {/* Dynamically-size circles based on route coordinates */}
                            {plotRouteCircles()}

                            {/* Placing a route or circle */}
                            {circles.map((circle, idx) => {
                                const imageX = (containerSize.width - image.width * scale) / 2;
                                const imageY = (containerSize.height - image.height * scale - paddingTop - paddingBottom) / 2 + paddingTop;

                                return (
                                    <React.Fragment key={`new-${idx}`}>
                                        <Circle
                                            x={circle.x * scale + imageX}
                                            y={circle.y * scale + imageY}
                                            radius={11}
                                            fill={placingColor}
                                            stroke="black"
                                            strokeWidth={0.5}
                                        />
                                        <Text
                                            x={circle.x * scale + imageX - 7}
                                            y={circle.y * scale + imageY - 5}
                                            text={grade}
                                            fontSize={12}
                                            fill="white"
                                            fontStyle="bold"
                                        />
                                    </React.Fragment>
                                );
                            })}
                        </Layer>
                    </Stage>
                )}
            </div>

        </div>
    );
};

export default Wall;


